script:
(function () {
  'use strict';
  // Roth 401(k) in-plan conversion (in-plan Roth rollover), optionally spread over several years.
  //   Each year y < N, at the start of the year: rolled = pre-tax balance left / (N - y); its after-tax
  //     basis share = basis left x rolled / balance left (pro rata). Taxable = rolled - basis share.
  //   Tax that year: federal = tax(income + taxable) - tax(income) on the 2026 ordinary brackets
  //     (held at 2026 levels for later years), state = flat rate x taxable. Paid from outside savings.
  //   Roll over: Roth balance grows at r and is tax-free; any pre-tax left is valued after tax.
  //   Keep: the whole pre-tax balance grows at r and is taxed at the retirement rate above its basis;
  //     the tax cash is invested in a taxable account at r x (1 - tax rate on returns) when it would
  //     have been paid. Break-even retirement rate = (keep balance + side account - Roth) / (keep balance - basis).
  //   First RMD avoided (keep path, untouched): balance at the prior Dec 31 / Uniform Lifetime factor.
  // Checked in Node (fake DOM, whole script, tests/rkc.test.js): single, $90,000 income + $60,000 in one
  //   year -> $14,086 ($15,700 at 22% + $44,300 at 24%); first of three $20,000 slices -> $4,486;
  //   single $0 income + $12,400 -> $1,240 (10% band); $10,000 after-tax basis -> $50,000 taxable;
  //   0% return, 1 year, untaxed side account -> break-even = effective rate (22%); $100,000 at 6% for
  //   20 years = $320,714; first RMD: born 1960, $100,000 at 0% -> $100,000 / 24.6 = $4,065 at 75;
  //   born 1959 -> / 26.5 = $3,774 at 73.
  //
  // ---- 2026 FEDERAL TAX FIGURES (tax year 2026) ---------------------------------------------------
  // Brackets: IRS Rev. Proc. 2025-32, section 4.01 (as amended by P.L. 119-21). Upper limit of each
  // band; rates 10, 12, 22, 24, 32, 35, 37%.
  var TAX_YEAR = 2026;
  var BRACKETS = {
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var EARLY_AGE = 59.5; // IRC 72(t); in-plan rollover recapture within 5 tax years (Pub. 575)
  // RMDs: Uniform Lifetime Table, IRS Pub. 590-B Appendix B Table III (ages 72-120). Start age
  // (SECURE 2.0 Act sec. 107): 73 if born 1951-1959, 75 if born 1960 or later. Designated Roth
  // accounts have no lifetime RMDs for 2024 and later (SECURE 2.0 Act sec. 325, IRC 402A(d)(5)).
  var UNIFORM_TABLE = {
    72: 27.4, 73: 26.5, 74: 25.5, 75: 24.6, 76: 23.7, 77: 22.9, 78: 22.0, 79: 21.1, 80: 20.2,
    81: 19.4, 82: 18.5, 83: 17.7, 84: 16.8, 85: 16.0, 86: 15.2, 87: 14.4, 88: 13.7, 89: 12.9,
    90: 12.2, 91: 11.5, 92: 10.8, 93: 10.1, 94: 9.5, 95: 8.9, 96: 8.4, 97: 7.8, 98: 7.3,
    99: 6.8, 100: 6.4
  };
  // ------------------------------------------------------------------------------------------------

  function tax(income, status) {
    var b = BRACKETS[status], t = 0, lower = 0;
    for (var k = 0; k < RATES.length; k++) {
      var upper = k < b.length ? b[k] : Infinity;
      if (income > lower) t += (Math.min(income, upper) - lower) * RATES[k];
      lower = upper;
    }
    return t;
  }
  function topRate(income, status) { // rate on the last dollar of income
    var b = BRACKETS[status];
    for (var k = 0; k < b.length; k++) if (income <= b[k]) return RATES[k];
    return RATES[RATES.length - 1];
  }
  function rmdStartAge(birthYear) { return birthYear <= 1950 ? 72 : birthYear <= 1959 ? 73 : 75; }

  // p: amount, basis, spread, income, status, stateRate, age, years, rate, retireRate, investTax
  function compute(p) {
    var pre = p.amount, basisLeft = p.basis, roth = 0;          // roll-over path
    var keep = p.amount, side = 0;                                 // keep path
    var sideRate = p.rate * (1 - p.investTax), plan = [], rows = [];
    var fedTotal = 0, stateTotal = 0, taxableTotal = 0;
    for (var y = 0; y < p.years; y++) {
      if (y < p.spread && pre > 0) {
        var rolled = pre / (p.spread - y);
        var basisPart = pre > 0 ? basisLeft * rolled / pre : 0;
        var taxable = Math.max(0, rolled - basisPart);
        var fed = tax(p.income + taxable, p.status) - tax(p.income, p.status);
        var st = taxable * p.stateRate;
        pre -= rolled; basisLeft -= basisPart; roth += rolled;
        side += fed + st;
        fedTotal += fed; stateTotal += st; taxableTotal += taxable;
        plan.push({ year: TAX_YEAR + y, age: p.age + y, rolled: rolled, taxable: taxable, fed: fed, state: st,
                    top: taxable > 0 ? topRate(p.income + taxable, p.status) : topRate(p.income, p.status) });
      }
      roth *= 1 + p.rate; pre *= 1 + p.rate; keep *= 1 + p.rate; side *= 1 + sideRate;
      var rollAfter = roth + pre - Math.max(0, pre - basisLeft) * p.retireRate;
      var keepAfter = keep - Math.max(0, keep - p.basis) * p.retireRate;
      rows.push({ age: p.age + y + 1, roth: roth, rollAfter: rollAfter, keepAfter: keepAfter, side: side,
                  diff: rollAfter - keepAfter - side });
    }
    var last = rows[rows.length - 1];
    var grown = Math.max(0, keep - p.basis);
    var oneYearTaxable = Math.max(0, p.amount - p.basis);
    return {
      plan: plan, rows: rows, fed: fedTotal, state: stateTotal, total: fedTotal + stateTotal, taxable: taxableTotal,
      oneYear: tax(p.income + oneYearTaxable, p.status) - tax(p.income, p.status) + oneYearTaxable * p.stateRate,
      first: plan.length ? plan[0].fed + plan[0].state : 0,
      rothEnd: last.rollAfter, keepEnd: last.keepAfter + last.side, diff: last.diff,
      breakEven: grown > 0 ? (keep + last.side - last.rollAfter) / grown : NaN
    };
  }
  function firstRmd(amount, rate, age) {
    var start = rmdStartAge(TAX_YEAR - age);
    if (age >= start) return null;
    return { age: start, year: TAX_YEAR + start - age,
             amount: amount * Math.pow(1 + rate, start - age) / UNIFORM_TABLE[start] };
  }

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmt(x) { return money.format(Math.abs(x) < 0.5 ? 0 : x); }
  function pct(x) { return (Math.round(x * 1000) / 10) + '%'; }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, t) { document.getElementById(id).textContent = t; }
  function fillTable(id, rows) {
    var body = document.getElementById(id);
    body.textContent = '';
    rows.forEach(function (cells) {
      var tr = document.createElement('tr');
      cells.forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  function update() {
    var amount = num('rkcAmount'), basis = num('rkcBasis'), spread = num('rkcSpread'), income = num('rkcIncome'),
        stateRate = num('rkcState'), age = num('rkcAge'), retireAge = num('rkcRetireAge'), rate = num('rkcRate'),
        retireRate = num('rkcRetireRate'), investTax = num('rkcInvestTax'), status = document.getElementById('rkcStatus').value;
    var error = document.getElementById('rkcError');
    var bad = [amount, basis, spread, income, stateRate, age, retireAge, rate, retireRate, investTax].some(isNaN) ||
              amount <= 0 || basis < 0 || basis > amount || spread < 1 || spread > 20 || spread !== Math.round(spread) ||
              income < 0 || stateRate < 0 || stateRate > 20 || age !== Math.round(age) || retireAge !== Math.round(retireAge) ||
              age < 18 || age > 90 || retireAge <= age || retireAge > 100 || spread > retireAge - age ||
              rate < -20 || rate > 30 || retireRate < 0 || retireRate > 70 || investTax < 0 || investTax > 70;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter an amount above $0 with after-tax contributions no larger than it, whole-number ages from 18 to 90 ' +
                          'with withdrawals starting later (up to 100), 1 to 20 rollover years that end by then, a state rate up to 20%, ' +
                          'a return from -20 to 30% and tax rates up to 70%.';
      return;
    }
    var r = compute({ amount: amount, basis: basis, spread: spread, income: income, status: status, stateRate: stateRate / 100,
                      age: age, years: retireAge - age, rate: rate / 100, retireRate: retireRate / 100, investTax: investTax / 100 });
    set('rkcTaxTotal', fmt(r.total));
    set('rkcRothEnd', fmt(r.rothEnd));
    set('rkcKeepEnd', fmt(r.keepEnd));
    set('rkcDiff', (Math.abs(r.diff) < 0.5 ? 'Even' : r.diff > 0 ? 'Roll over: +' + fmt(r.diff) : 'Keep pre-tax: +' + fmt(-r.diff)));
    set('rkcAgeLabel', 'At age ' + retireAge + ', after tax. Keeping pre-tax includes the invested tax money.');
    set('rkcTaxable', fmt(r.taxable));
    set('rkcFedState', fmt(r.fed) + ' / ' + fmt(r.state));
    set('rkcEffective', r.taxable > 0 ? pct(r.total / r.taxable) : '0%');
    set('rkcOneYear', fmt(r.oneYear) + (spread > 1 ? (r.oneYear - r.total >= 0.5 ? ' (spreading saves ' + fmt(r.oneYear - r.total) + ')' : ' (spreading costs more here: later growth is taxed too)') : ''));
    set('rkcFirstYear', fmt(r.first));
    set('rkcBreakEven', isFinite(r.breakEven) ? (r.breakEven <= 0 ? 'Rolling over wins at any rate' :
        r.breakEven >= 1 ? 'Keeping pre-tax wins at any rate' : 'Rolling over wins above ' + pct(r.breakEven)) : 'No taxable growth');
    var lastYear = TAX_YEAR + spread - 1;
    set('rkcFiveYear', 'December 31, ' + (lastYear + 4));
    var five = document.getElementById('rkcFiveNote');
    five.hidden = !(age < EARLY_AGE);
    set('rkcFiveNote', 'You are under 59½. Each year’s rollover starts its own 5-year period; taking out the taxable part of a rollover ' +
        'before both that period ends and you reach 59½ triggers the 10% additional tax.');
    var rmd = firstRmd(amount, rate / 100, age);
    set('rkcRmd', rmd ? fmt(rmd.amount) + ' at age ' + rmd.age + ' (' + rmd.year + ')' : 'Already due: an RMD can’t be rolled over');
    fillTable('rkcPlan', r.plan.map(function (x) {
      return [x.year, x.age, fmt(x.rolled), fmt(x.taxable), fmt(x.fed), fmt(x.state), pct(x.top)];
    }));
    fillTable('rkcSchedule', r.rows.map(function (x) {
      return [x.age, fmt(x.roth), fmt(x.rollAfter), fmt(x.keepAfter), fmt(x.side), fmt(x.diff)];
    }));
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('rkcForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
